<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';
import {useRoute} from 'vue-router';
import {getVisitorState,postVisitor,type VPayload} from './visitor-content-api';
const route=useRoute(),payload=ref<VPayload|null>(null),selectedTheme=ref('water'),query=ref(''),message=ref(''),busy=ref(false),selectedPlaces=ref<string[]>([]),selectedContents=ref<string[]>([]);
const edits=reactive<Record<string,{themeIds:string[];familyFriendly:boolean;version:number}>>({});
async function load(){payload.value=await getVisitorState();for(const p of payload.value.places){const a=payload.value.state.placeAssignments.find(x=>x.placeCode===p.code);edits[p.code]={themeIds:[...(a?.themeIds||[])],familyFriendly:a?.familyFriendly||false,version:a?.version||0};}if(route.query.place)query.value=String(route.query.place);}
onMounted(load);
const places=computed(()=>payload.value?.places.filter(p=>!p.deleted_at&&!p.duplicate_of_place_id&&[p.code,p.name,...p.old_names].some(v=>v.toLowerCase().includes(query.value.trim().toLowerCase())))||[]);
async function savePlace(code:string){const e=edits[code];busy.value=true;try{await postVisitor('/place-themes',{place_code:code,expected_version:e.version,theme_ids:e.themeIds,family_friendly:e.familyFriendly});message.value='该地点的主题与适合带孩子已一次保存';await load();}catch(error){message.value=(error as Error).message;}finally{busy.value=false;}}
function prepareBatch(){selectedPlaces.value=payload.value?.state.placeAssignments.filter(a=>a.themeIds.includes(selectedTheme.value)).map(a=>a.placeCode)||[];selectedContents.value=payload.value?.state.contents.filter(c=>!c.deletedAt&&c.draft.themeIds.includes(selectedTheme.value)).map(c=>c.id)||[];}
async function applyBatch(){busy.value=true;try{await postVisitor('/themes/batch',{expected_store_version:payload.value!.state.version,theme_id:selectedTheme.value,place_codes:selectedPlaces.value,content_ids:selectedContents.value});message.value='地点和内容单元的批量主题已原子保存';await load();}catch(error){message.value=(error as Error).message;}finally{busy.value=false;}}
</script>
<template><div class="workspace-page"><div class="workspace-title"><div><p class="kicker">展示层映射</p><h1>游客主题</h1><p>一个地点可以属于多个主题；适合带孩子是独立筛选。</p></div></div><p v-if="message" class="inline-message">{{message}}</p><section class="content-toolbar"><label class="content-search"><span>查找地点</span><input v-model="query" placeholder="当前名称、曾用名或 WY 编号"></label></section><div class="theme-matrix"><article v-for="place in places" :key="place.code"><div><strong>{{place.name}}</strong><small>{{place.code}}</small></div><div class="theme-checks"><label v-for="theme in payload?.state.themes" :key="theme.id"><input v-model="edits[place.code].themeIds" type="checkbox" :value="theme.id">{{theme.name}}</label><label class="family-check"><input v-model="edits[place.code].familyFriendly" type="checkbox">适合带孩子</label><button :disabled="busy" @click="savePlace(place.code)">保存</button></div></article></div><section class="batch-panel"><div class="section-heading"><span>批量</span><div><h2>按一个主题批量核对</h2><p>地点和内容单元一次提交，校验失败则整批不写入。</p></div></div><div class="add-row"><select v-model="selectedTheme"><option v-for="t in payload?.state.themes" :value="t.id">{{t.name}}</option></select><button class="secondary" @click="prepareBatch">载入当前选择</button><button @click="applyBatch">保存批量调整</button></div><h3>正常可维护地点</h3><div class="batch-grid"><label v-for="place in payload?.places.filter(p=>!p.deleted_at&&!p.duplicate_of_place_id)" :key="place.code"><input v-model="selectedPlaces" type="checkbox" :value="place.code">{{place.name}} <small>{{place.code}}</small></label></div><h3>游客内容单元</h3><div class="batch-grid compact"><label v-for="content in payload?.state.contents.filter(c=>!c.deletedAt)" :key="content.id"><input v-model="selectedContents" type="checkbox" :value="content.id">{{content.draft.title}}</label></div></section></div></template>
